<?php require_once 'config.php';require_admin();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$kind=$_POST['kind']??'';$id=(int)($_POST['id']??0);$status=$_POST['status']??'';if($kind==='application'&&in_array($status,['submitted','reviewing','approved','rejected'],true)){$st=$pdo->prepare('UPDATE applications SET status=? WHERE id=?');$st->execute([$status,$id]);flash('Estado da candidatura actualizado.');}elseif($kind==='booking'&&in_array($status,['requested','confirmed','completed','cancelled'],true)){$st=$pdo->prepare('UPDATE mentorship_bookings SET status=? WHERE id=?');$st->execute([$status,$id]);flash('Estado do pedido de mentoria actualizado.');}header('Location: admin.php');exit;}$page_title='Administração | Kuntima';$apps=$pdo->query('SELECT a.id,a.status,a.applied_at,u.name AS student,s.title AS scholarship FROM applications a JOIN users u ON u.id=a.user_id JOIN scholarships s ON s.id=a.scholarship_id ORDER BY a.applied_at DESC')->fetchAll();$bookings=$pdo->query('SELECT b.id,b.status,b.session_date,u.name AS student,m.title AS service FROM mentorship_bookings b JOIN users u ON u.id=b.student_id JOIN mentorship_services m ON m.id=b.service_id ORDER BY b.created_at DESC')->fetchAll();$stats=[$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn(),$pdo->query('SELECT COUNT(*) FROM scholarships')->fetchColumn(),count($apps)];require 'includes/header.php'; ?>
<div class="page-heading"><span class="eyebrow" style="color:var(--green)">Gestão da plataforma</span><h1>Administração</h1><p>Consulta e actualiza o estado das candidaturas e sessões solicitadas.</p></div><div class="dashboard-stats"><div class="stat"><span>Utilizadores</span><strong><?=$stats[0]?></strong></div><div class="stat"><span>Bolsas cadastradas</span><strong><?=$stats[1]?></strong></div><div class="stat"><span>Candidaturas</span><strong><?=$stats[2]?></strong></div></div><section class="section" style="padding-top:5px"><div class="section-head"><div><h2>Candidaturas</h2><p>Actualiza o estado para informar o estudante.</p></div></div><?php if($apps): ?><div class="table-wrap"><table><thead><tr><th>Estudante</th><th>Bolsa</th><th>Submetida</th><th>Estado</th><th>Actualizar</th></tr></thead><tbody><?php foreach($apps as $a): ?><tr><td><?=e($a['student'])?></td><td><?=e($a['scholarship'])?></td><td><?=e(date('d/m/Y',strtotime($a['applied_at'])))?></td><td><?=e($a['status'])?></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="kind" value="application"><input type="hidden" name="id" value="<?=$a['id']?>"><select name="status" aria-label="Estado da candidatura"><option value="submitted" <?=$a['status']==='submitted'?'selected':''?>>Submetida</option><option value="reviewing" <?=$a['status']==='reviewing'?'selected':''?>>Em análise</option><option value="approved" <?=$a['status']==='approved'?'selected':''?>>Aprovada</option><option value="rejected" <?=$a['status']==='rejected'?'selected':''?>>Não aprovada</option></select> <button class="btn-small">Guardar</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty">Ainda não existem candidaturas.</div><?php endif; ?></section><section class="section"><div class="section-head"><div><h2>Pedidos de mentoria</h2><p>Confirma, conclui ou cancela pedidos de sessão.</p></div></div><?php if($bookings): ?><div class="table-wrap"><table><thead><tr><th>Estudante</th><th>Serviço</th><th>Data pretendida</th><th>Estado</th><th>Actualizar</th></tr></thead><tbody><?php foreach($bookings as $b): ?><tr><td><?=e($b['student'])?></td><td><?=e($b['service'])?></td><td><?=e(date('d/m/Y H:i',strtotime($b['session_date'])))?></td><td><?=e($b['status'])?></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="kind" value="booking"><input type="hidden" name="id" value="<?=$b['id']?>"><select name="status" aria-label="Estado da mentoria"><option value="requested" <?=$b['status']==='requested'?'selected':''?>>Pendente</option><option value="confirmed" <?=$b['status']==='confirmed'?'selected':''?>>Confirmada</option><option value="completed" <?=$b['status']==='completed'?'selected':''?>>Concluída</option><option value="cancelled" <?=$b['status']==='cancelled'?'selected':''?>>Cancelada</option></select> <button class="btn-small">Guardar</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty">Ainda não existem pedidos de mentoria.</div><?php endif; ?></section><?php require 'includes/footer.php'; ?>
